// Fusionner et dédupliquer les conversations de LinkedIn et Instagram
const linkedinData = $('Playwright – Lire DMs LinkedIn').item.json;
const instagramData = $('Playwright – Lire DMs Instagram').item.json;

const conversations = [];

(linkedinData.conversations || []).forEach(c => {
  if (c.messages && c.messages.length > 0) {
    const lastMsg = c.messages[c.messages.length - 1];
    // Ne traiter que les messages entrants (pas les nôtres)
    if (!lastMsg.isOwn) {
      conversations.push({
        platform: 'linkedin',
        senderName: c.senderName,
        lastMessage: lastMsg.text,
        allMessages: c.messages.map(m => m.text || m).join('\n'),
        conversationUrl: c.url,
        messageCount: c.messages.length,
      });
    }
  }
});

(instagramData.conversations || []).forEach(c => {
  if (c.messages && c.messages.length > 0) {
    conversations.push({
      platform: 'instagram',
      senderName: 'unknown',
      lastMessage: c.messages[c.messages.length - 1],
      allMessages: c.messages.join('\n'),
      conversationUrl: c.url,
      messageCount: c.messages.length,
    });
  }
});

return conversations.map(c => ({ json: c }));

