const claudeResp = $input.item.json;
const conversation = $('Fusionner conversations').item.json;

let analysis;
try {
  const text = claudeResp.content[0].text.trim();
  analysis = JSON.parse(text);
} catch (e) {
  analysis = { intent: 'neutral', urgency: 'low', score: 3, requiresHuman: false, suggestedAction: 'reply', summary: 'Parsing error' };
}

return [{
  json: {
    ...conversation,
    analysis,
    needsHumanEscalation: analysis.requiresHuman || analysis.score >= 9,
    shouldAutoReply: analysis.suggestedAction === 'reply' && !analysis.requiresHuman && analysis.score < 9,
  }
}];

